# Parse old_songs.txt to extract song titles and artists
old_songs = []
for line in old_songs_file['content'].splitlines():
    line = line.strip()
    if line.startswith('- '):
        line = line[2:]
        if ' by ' in line:
            title, artists_str = line.split(' by ', 1)
            artists = [a.strip() for a in artists_str.split(',')]
            old_songs.append({'title': title.strip(), 'artists': set(artists)})
print(f"Parsed {len(old_songs)} old songs")
for s in old_songs:
    print(f"  {s['title']} by {', '.join(sorted(s['artists']))}")

# Get songs from each playlist
playlists_songs = {}
for pl in all_playlists:
    pl_id = pl['playlist_id']
    pl_detail = apis.spotify.show_playlist(playlist_id=pl_id, access_token=spotify_login['access_token'])
    playlists_songs[pl_id] = pl_detail['songs']
    print(f"Playlist {pl_id} ({pl['title']}): {len(pl_detail['songs'])} songs")
    for s in pl_detail['songs']:
        print(f"  song_id={s['id']} title={s['title']} artist_ids={s['artist_ids']}")

