# Compute matched song IDs by comparing song details with old_songs_set
matched_song_ids = []
for playlist in all_playlists:
    for song_id in playlist['song_ids']:
        if song_id in song_details:
            details = song_details[song_id]
            title = details['title'].lower()
            artists = frozenset([artist['name'].lower() for artist in details['artists']])
            if (title, artists) in old_songs_set:
                if song_id not in matched_song_ids:
                    matched_song_ids.append(song_id)

print("Matched song IDs:", matched_song_ids)
print("Count:", len(matched_song_ids))

# Remove matched songs from all playlists
for playlist in all_playlists:
    playlist_id = playlist['playlist_id']
    for song_id in matched_song_ids:
        if song_id in playlist['song_ids']:
            result = apis.spotify.remove_song_from_playlist(playlist_id=playlist_id, song_id=song_id, access_token=spotify_token)
            print(f"Removed song {song_id} from playlist {playlist_id}: {result}")

