# Process each playlist: remove archived songs and add them to Old Songs
archive_song_ids = {song_id for song_id, _, _ in song_ids_to_archive}
old_songs_playlist_id = 654
added_to_old = set()  # track song_ids already added to Old Songs

for pl in all_playlists:
    pl_id = pl['playlist_id']
    if pl_id == old_songs_playlist_id:
        continue  # skip Old Songs playlist itself
    # Get playlist details to see its songs
    pl_details = apis.spotify.show_playlist(playlist_id=pl_id, access_token=login_result["access_token"])
    songs = pl_details.get('songs', [])
    # Find songs in this playlist that are in archive list
    to_remove = [song for song in songs if song['id'] in archive_song_ids]
    if to_remove:
        print(f"Playlist '{pl['title']}' (ID {pl_id}) has {len(to_remove)} songs to archive:")
        for song in to_remove:
            print(f"  - {song['title']} (ID {song['id']})")
    else:
        print(f"Playlist '{pl['title']}' (ID {pl_id}) has no songs to archive.")

# Fetch details for all unique song IDs to match against archive list
song_details = {}
for sid in all_song_ids:
    song_info = apis.spotify.show_song(song_id=sid, access_token=login_result['access_token'])
    song_details[sid] = song_info
print("Fetched details for", len(song_details), "songs")

# Build mapping from (title, artist) to song_id
song_map = {}
for sid, info in song_details.items():
    title = info['title']
    for artist_info in info['artists']:
        artist = artist_info['name']
        song_map[(title, artist)] = sid
print("Song map size:", len(song_map))

# Find song IDs that match archive list
archive_song_ids = set()
for song in songs_to_archive:
    key = (song['title'], song['artist'])
    if key in song_map:
        archive_song_ids.add(song_map[key])
    else:
        print("Not found in playlists:", key)
print("Archive song IDs found:", sorted(archive_song_ids))

