steps.code:
# Let's adjust the parsing to use sorted tuples for artists and print properly.
old_songs = set()
for line in file_data['content'].splitlines():
    line = line.strip()
    if not line or line.startswith('#'):
        continue
    if line.startswith('- '):
        line = line[2:]
    if ' by ' in line:
        title_part, artists_part = line.split(' by ', 1)
        title = title_part.strip()
        artists = tuple(sorted(a.strip() for a in artists_part.split(',')))
        old_songs.add((title, artists))
    else:
        # skip malformed
        pass

print(f"Parsed {len(old_songs)} old songs")
for s in sorted(old_songs):
    print(s)

