steps.code:
# Let's parse the note content to extract all songs and identify those with TODO
content = note['content']
lines = content.split('\n')
songs = []
for line in lines:
    if line.startswith('- '):
        # Format: - Song Title BY Artist1, Artist2 RELEASED_AT MM/YYYY
        # Remove leading "- "
        line = line[2:]
        # Split on " BY " to get title and rest
        if ' BY ' in line:
            title_part, rest = line.split(' BY ', 1)
            # rest contains artists and RELEASED_AT
            # Split on " RELEASED_AT " to get artists and release
            if ' RELEASED_AT ' in rest:
                artists_part, release = rest.split(' RELEASED_AT ', 1)
                songs.append({'title': title_part.strip(), 'artists': artists_part.strip(), 'release': release.strip()})
            else:
                # No RELEASED_AT? Shouldn't happen
                songs.append({'title': title_part.strip(), 'artists': rest.strip(), 'release': None})
        else:
            # Malformed line, skip
            pass

# Print songs with TODO
for s in songs:
    if s['release'] == 'TODO':
        print(s['title'], '|', s['artists'])
    else:
        print('DONE:', s['title'], '|', s['artists'], '|', s['release'])

