steps.code:
# Search for each TODO song to get release date
todo_songs = [s for s in songs if s['released'] == 'TODO']
for s in todo_songs:
    result = apis.spotify.search_songs(query=s['title'], access_token=spotify_token, page_limit=20)
    # Find matching song by title and artist
    found = None
    for song in result:
        if song['title'].lower() == s['title'].lower():
            # Check if any artist matches
            note_artists = [a.strip() for a in s['artists'].split(',')]
            song_artists = [a['name'] for a in song['artists']]
            if any(na.lower() in [sa.lower() for sa in song_artists] for na in note_artists):
                found = song
                break
    if found:
        print(f"{s['title']} -> {found['release_date']}")
    else:
        print(f"NOT FOUND: {s['title']}")

