result = apis.spotify.search_songs(query='Lost in the Embrace of Night', access_token=spotify_token, page_limit=20)
# Filter for exact title and artist
for song in result:
    if song['title'].lower() == 'lost in the embrace of night':
        artists = [a['name'] for a in song['artists']]
        if 'Noah Bennett' in artists:
            print(song['song_id'], song['title'], artists, song['release_date'])
            break

# Search for "Lonely Skies" by Aria Sterling
result = apis.spotify.search_songs(query='Lonely Skies', access_token=spotify_token, page_limit=20)
for song in result:
    if song['title'].lower() == 'lonely skies':
        artists = [a['name'] for a in song['artists']]
        if 'Aria Sterling' in artists:
            print(song['song_id'], song['title'], artists, song['release_date'])
            break

# Search for "Caught in a Web of Lies"
result = apis.spotify.search_songs(query='Caught in a Web of Lies', access_token=spotify_token, page_limit=20)
for song in result:
    if song['title'].lower() == 'caught in a web of lies':
        artists = [a['name'] for a in song['artists']]
        if 'Hazel Winter' in artists and 'Ava Morgan' in artists:
            print(song['song_id'], song['title'], artists, song['release_date'])
            break

