steps.code:
# Process all TODO songs: search and get release dates
from datetime import datetime

release_dates = {}
for song_info in todo_songs:
    title = song_info['title']
    artists = song_info['artists']
    result = apis.spotify.search_songs(query=title, access_token=spotify_token, page_limit=20)
    matching = None
    for song in result:
        if song['title'].lower() == title.lower():
            song_artists = [a['name'] for a in song['artists']]
            # Check all note artists are present in song artists
            if all(any(artist.lower() in sa.lower() for sa in song_artists) for artist in artists):
                matching = song
                break
    if matching:
        dt = datetime.fromisoformat(matching['release_date'])
        month_year = f"{dt.month:02d}/{dt.year}"
        release_dates[title] = month_year
        print(f"{title} -> {month_year}")
    else:
        print(f"NO MATCH for {title}")

print("Done")

