steps.code:
# Parse the note content to extract songs and their release status
content = note['content']
lines = content.strip().split('\n')
songs = []
for line in lines:
    if line.startswith('- '):
        # Remove leading "- "
        entry = line[2:]
        # Split by " BY " to get title and artist part
        if ' BY ' in entry:
            title_part, artist_part = entry.split(' BY ', 1)
            # Check if it has RELEASED_AT
            if ' RELEASED_AT ' in artist_part:
                artist_part, released = artist_part.split(' RELEASED_AT ', 1)
                released = released.strip()
            else:
                released = None
            songs.append({
                'title': title_part.strip(),
                'artists': artist_part.strip(),
                'released': released
            })
print(songs)

