# Remove all liked songs from the queue, iterating from the end to avoid index shifting
liked_ids = {58, 60, 82, 130, 132, 134, 219, 251, 265, 268, 275}
for pos in range(len(queue)-1, -1, -1):
    if queue[pos]['song_id'] in liked_ids:
        result = apis.spotify.remove_song_from_queue(access_token=access_token, position=pos)
        print(f"Removed position {pos} (song_id={queue[pos]['song_id']}): {result}")

